class Solution {
    ListNode* curr;

    TreeNode* build(int lo, int hi) {
        if (lo > hi) return nullptr;
        int mid = lo + (hi - lo + 1) / 2;
        TreeNode* left = build(lo, mid - 1);
        TreeNode* node = new TreeNode(curr->val);
        curr = curr->next;
        node->left = left;
        node->right = build(mid + 1, hi);
        return node;
    }

public:
    TreeNode* sortedListToBST(ListNode* head) {
        int n = 0;
        ListNode* p = head;
        while (p) {
            n++;
            p = p->next;
        }
        curr = head;
        return build(0, n - 1);
    }
};
